import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, TextureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  // Load the featured image texture
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Create plane geometry with 512:320 aspect ratio
  const aspectRatio = 512 / 320;
  const geometry = new THREE.PlaneGeometry(aspectRatio, 1.0);

  // Create TSL-based material with texture color node
  const colorNode = new TextureNode(texture);
  const material = new MeshBasicNodeMaterial({ colorNode });

  // Create mesh and add to group
  const mesh = new THREE.Mesh(geometry, material);
  const group = new THREE.Group();
  group.add(mesh);

  // Apply cinematic primitives if specified
  if (config.cinematicPrimitives?.length) {
    for (const primitive of config.cinematicPrimitives) {
      ctx.primitives[primitive.name](group, primitive.params);
    }
  }

  // Cleanup handler for resource disposal
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  // Event handlers (none for this static card)
  group.userData.handlers = {};

  return group;
}
